import { test, expect, mock } from 'bun:test';
import { follower, feed, tempo } from './clockin.js';

// These modules are copied or generated by the web build.
mock.module('./navigation.js', () => import('../web/navigation.js'));
mock.module('./prompt-glue.js', () => ({}));
mock.module('./alert-message.js', () => ({}));
mock.module('./menu-rows.js', () => ({}));
mock.module('./names.js', () => ({ sourceTypes: {} }));
const { clock, Sounds, advance, data, journal } = await import('./rt.js');
const { install } = await import('./sounds.js');
const { midi } = await import('./midi.js');
const { sequence, transport } = await import('./transport.js');
clock.agent = true;
data.grants = '';
install([]);
midi({}, true);
transport({});

const ticks = (from, interval, n) => Array.from({ length: n }, (_, k) => [from + k * interval, [0xF8]]);
const change = () => { Sounds.gate(); Sounds.stood(); };
const now = byte => Sounds.clockIn([[clock.now, [byte]]]);

test('MIDI grants use Rust whitespace and keep FEFF significant', () => {
  try {
    for (const [grants, state] of [
      ['device.midi purpose.midi', 'prompt'],
      ['device.midi\u0085purpose.midi', 'prompt'],
      ['\u0085device.midi\tpurpose.midi\u0085', 'prompt'],
      ['\ufeffdevice.midi purpose.midi', 'denied'],
    ]) {
      data.grants = grants;
      midi({ ports: [['state'], {}] }, false);
      expect(data.reserved.exactMIDI(null, [], 'ports')).toEqual([state]);
    }
  } finally { data.grants = ''; midi({}, true); }
});

function runClock(bpm, ms) {
  const start = clock.now, interval = 60000 / (24 * bpm);
  let k = 1, edge = start;
  while (edge < start + ms) {
    edge = Math.min(edge + 50, start + ms);
    const slice = [];
    while (start + k * interval <= edge) slice.push([start + k++ * interval, [0xF8]]);
    advance(edge, false);
    Sounds.clockIn(slice);
  }
}
function play(length = 1, extra = []) {
  const p = { on: true, length };
  sequence([[() => p.on, null, () => [
    [[p.length, 0, 0, '', [[0, '', 1, '', 36, 100, 9, 0.25, '']]], ...extra], 120, 0, [], 'clk', '',
  ], null, 's']]);
  p.stop = () => { p.on = false; change(); };
  return p;
}

test('a clock burst keeps the prior or last valid tempo', () => {
  for (const gap of [0.999, 0.001, 0.000001, Number.MIN_VALUE]) {
    const f = follower('clk', 90, 0);
    feed(f, ticks(0, gap, 29), 's', () => {});
    expect([f.estimate, tempo(f)]).toEqual([null, 90]);
    feed(f, ticks(1000, 1, 48), 's', () => {});
    expect(f.estimate).toBe(2500);
    feed(f, ticks(2000, gap, 29), 's', () => {});
    expect(f.estimate).toBe(2500);
    feed(f, ticks(3000, 25, 48), 's', () => {});
    expect(f.estimate).toBe(100);
  }
});

test('a clock burst after a gap does not expand the fill', () => {
  const p = play();
  try {
    now(0xFA);
    runClock(120, 2000);
    advance(clock.now + 600, false);
    const before = exact.transport.state().follow.estimate, sent = exact.midi.state().recorded;
    Sounds.clockIn(ticks(clock.now - 28 * 0.001, 0.001, 29));
    expect(exact.transport.state().follow.estimate).toBe(before);
    advance(clock.now + 200, false);
    expect(exact.midi.state().recorded - sent).toBeLessThanOrEqual(4);
  } finally { p.stop(); }
});

test('a followed tempo bounds tracks at start, re-anchor and edit', () => {
  for (const when of ['start', 'reanchor', 'edit']) {
    const p = play(when === 'edit' ? 1 : 0.004), first = journal.length;
    try {
      if (when !== 'start') now(0xFA);
      runClock(1250, 50);
      if (when === 'start') now(0xFA);
      if (when === 'edit') { p.length = 0.004; change(); }
      expect(journal.slice(first).some(line => line.includes('would loop more than 1000 times a second'))).toBe(true);
      advance(clock.now + 100, false);
      expect(exact.transport.state().state).toBe('stopped');
      expect(exact.transport.state().reason).toBe('ended');
    } finally { p.stop(); }
  }
});

test('dropping a fast track keeps the other track’s hits and end', () => {
  const p = play(0.004, [[1, 2, 0, '', [[0.13, '', 1, '', 42, 100, 9, 0.25, '']]]]);
  try {
    now(0xFA);
    runClock(1250, 50);
    const ons = exact.midi.state(true).sent.filter(s => s.data === '99 2a 64' && s.by == null);
    expect(ons.length).toBe(2);
    advance(clock.now + 200, false);
    expect(exact.transport.state().reason).toBe('ended');
  } finally { p.stop(); }
});
